var __index = {"config":{"lang":["en"],"separator":"[\\s\\u200b\\u3000\\-\u3001\u3002\uff0c\uff0e\uff1f\uff01\uff1b]+","pipeline":["stemmer"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"Air is Full","text":"<p>\u7ad9\u70b9\u7b80\u4ecb</p> <p>\u300cAir is Full\u300d\u2014\u2014\u5173\u4e8e\u7ad9\u70b9\u7684\u540d\u5b57\uff0c\u6211\u66fe\u60f3\u81ea\u4f5c\u4e00\u756a\u89e3\u91ca\uff0c\u4f46\u8f6c\u5ff5\u4e00\u60f3\uff1a\u4e00\u8bf4\u7834\uff0c\u610f\u5883\u4fbf\u7a84\u4e86\u3002\u4e8e\u662f\u51b3\u5b9a\u4e0d\u7ed9\u8bfb\u8005\u5077\u61d2\u7684\u673a\u4f1a\uff0c\u7559\u7ed9\u4f60\u4eb2\u81ea\u60f3\u8c61\u4e0e\u586b\u5145\uff0c\u6216\u8bb8\u6536\u83b7\u66f4\u5927\u3002</p> <p>\u8fd9\u4e2a\u7ad9\u70b9\uff0c\u662f\u6211\u4e3a\u81ea\u5df1\u642d\u5efa\u7684\u300c\u751f\u6d3b\u7248\u672c\u7ba1\u7406\u7cfb\u7edf\u300d\uff0c\u7528\u4e8e\u590d\u76d8\u8fc7\u5f80\uff0c\u91cd\u6784\u5f53\u4e0b\uff0c\u8fed\u4ee3\u672a\u6765\u3002</p>"},{"location":"index.html#_1","title":"\u7ad9\u70b9\u5165\u53e3","text":"<ul> <li> <p>Think about it | \ud83e\udd17</p> <p>\u4fee\u884c\u548c\u6210\u957f\u7684\u7ad9\u70b9\u3002</p> </li> <li> <p>Code on Farm | \ud83c\udf31</p> <p>\u4e13\u6ce8\u4e8e\u79d1\u5b66\u6280\u672f\u7684\u7ad9\u70b9\u3002</p> </li> <li> <p>Fly in Air | \u2601\ufe0f</p> <p>\u4e13\u6ce8\u4e8e\u8bb0\u5f55\u60f3\u6cd5\u548c\u6fc0\u53d1\u60f3\u8c61\u529b\u7684\u7ad9\u70b9\u3002</p> </li> <li> <p>Walk to Heart | \u2764\ufe0f</p> <p>\u4e13\u6ce8\u4e8e\u63a2\u7d22\u81ea\u6211\u7684\u7ad9\u70b9\u3002</p> </li> </ul>"},{"location":"index.html#_2","title":"\u7f18\u8d77","text":"<p>\u65f6\u5e38\u89c9\u5f97\u81ea\u5df1\u88ab\u4e00\u80a1\u65e0\u5f62\u7684\u529b\u91cf\u88f9\u631f\u7740\u524d\u884c\uff0c\u50cf\u7f6e\u8eab\u4e8e\u6e4d\u6025\u7684\u6cb3\u6d41\u2014\u2014\u76f2\u76ee\u6323\u624e\u53ea\u4f1a\u5f92\u8017\u6c14\u529b\uff0c\u5230\u5934\u6765\u4e8b\u500d\u529f\u534a\u3002\u5f85\u5230\u7b4b\u75b2\u529b\u5c3d\uff0c\u4fbf\u987a\u52bf\u8eba\u5e73\uff0c\u4efb\u7531\u81ea\u5df1\u9893\u5e9f\u3001\u6446\u70c2\u4e0b\u53bb\u3002</p> <p>\u53ef\u5fc3\u5e95\u603b\u6709\u4e2a\u58f0\u97f3\u5728\u95ee\uff1a\u5982\u4f55\u624d\u80fd\u91cd\u65b0\u638c\u63e1\u81ea\u5df1\u7684\u4eba\u751f\uff1f\u5982\u4f55\u771f\u6b63\u6d3b\u6210\u81ea\u5df1\u60f3\u8981\u7684\u6837\u5b50\uff1f</p> <p>\u751f\u6d3b\u662f\u6d41\u52a8\u7684\uff0c\u6211\u4eec\u6bcf\u5929\u90fd\u5728\u5e94\u5bf9\u53d8\u5316\u3001\u63a5\u53d7\u53d8\u5316\uff0c\u6700\u7ec8\u81ea\u5df1\u4e5f\u4f1a\u6709\u610f\u65e0\u610f\u7684\u53d1\u751f\u53d8\u5316\u3002</p> <p>\u5c31\u5982\u6211\u5199\u6587\u7ae0\u65f6\uff0c\u4e00\u8fb9\u5199\u4e00\u8fb9\u601d\u8003\uff0c\u4e00\u8fb9\u7ec4\u7ec7\u8bed\u8a00\u3002\u56e0\u4e3a\u80fd\u529b\u6709\u9650\uff0c\u65e0\u6cd5\u4e00\u6c14\u5475\u6210\u5730\u505a\u5230\u9762\u9762\u4ff1\u5230\u3001\u6e05\u6670\u6613\u61c2\u3002\u6240\u4ee5\u5199\u5b8c\u53ea\u662f\u5f00\u59cb\u2014\u2014\u6211\u5fc5\u987b\u5c06\u90a3\u4e9b\u6587\u5b57\u5438\u6536\u3001\u6467\u6bc1\u3001\u518d\u91cd\u6784\uff0c\u624d\u80fd\u8ba9\u5b83\u79bb\u5b8c\u7f8e\u66f4\u8fd1\u4e00\u6b65\u3002</p> <p>\u521b\u5efa\u8fd9\u4e2a\u4e2a\u4eba\u7f51\u7ad9\u65f6\uff0c\u6211\u4e5f\u7ecf\u5386\u4e86\u540c\u6837\u7684\u8fc7\u7a0b\u3002\u63a8\u5012\u91cd\u6765\u4e86\u597d\u51e0\u904d\uff0c\u5374\u53d1\u73b0\u6bcf\u4e00\u6b21\u4ece\u5934\u518d\u6765\uff0c\u90fd\u8ba9\u6211\u66f4\u6e05\u695a\u81ea\u5df1\u60f3\u8981\u4ec0\u4e48\uff0c\u64cd\u4f5c\u4e5f\u66f4\u52a0\u719f\u7ec3\u3002\u5f53\u7136\uff0c\u5e76\u975e\u6bcf\u6b21\u90fd\u8981\u5927\u52a8\u5e72\u6208\u5730\u4ece\u96f6\u5f00\u59cb\u2014\u2014\u8fd9\u662f\u4e00\u4e2a\u5b9a\u671f\u53cd\u7701\u7684\u8fc7\u7a0b\uff0c\u5c06\u7eb7\u4e71\u7684\u601d\u7eea\u91cd\u65b0\u68b3\u7406\u6210\u6709\u6761\u7406\u7684\u7ed3\u6784\u3002</p> <p>\u6587\u7ae0\u5982\u6b64\uff0c\u751f\u6d3b\u4ea6\u7136\u3002</p> <p>\u552f\u6709\u61c2\u5f97\u52a8\u9759\u4e4b\u95f4\u7684\u5e73\u8861\uff0c\u62e5\u6709\u6467\u6bc1\u4e0e\u91cd\u6784\u7684\u52c7\u6c14\uff0c\u624d\u80fd\u5728\u8fd9\u6e4d\u6025\u7684\u6cb3\u6d41\u4e2d\uff0c\u6e38\u5f97\u6e05\u723d\uff0c\u6d3b\u5f97\u81ea\u5728\u3002</p>"},{"location":"about.html","title":"About","text":""},{"location":"authors/linxinji.html","title":"\ud83d\udc4b \u4f60\u597d\uff0c\u6211\u662f \u6797\u6b23\u7a37","text":"<p>\u559c\u6b22\u7528\u4ee3\u7801\u89e3\u51b3\u95ee\u9898\u7684\u524d\u7aef\u5de5\u7a0b\u5e08 / \u7ec8\u8eab\u5b66\u4e60\u8005 / \u751f\u6d3b\u590d\u76d8\u7231\u597d\u8005</p>"},{"location":"authors/linxinji.html#_2","title":"\ud83d\udccc \u5173\u4e8e\u6211","text":"<ul> <li>\ud83d\udd2d \u76ee\u524d\u6b63\u5728\u63a2\u7d22 Vue 3 + TypeScript \u7684\u6700\u4f73\u5b9e\u8df5</li> <li>\ud83c\udf31 \u6700\u8fd1\u5728\u5b66\u4e60\uff1a\u51fd\u6570\u5f0f\u7f16\u7a0b\u3001\u9053\u5bb6\u54f2\u5b66\u4e0e\u7cfb\u7edf\u601d\u7ef4\u7684\u4ea4\u53c9\u5e94\u7528</li> <li>\ud83d\udcac \u6b22\u8fce\u4ea4\u6d41\u5173\u4e8e \u524d\u7aef\u5f00\u53d1\u3001\u4e2a\u4eba\u590d\u76d8\u3001\u5199\u4f5c \u7684\u4efb\u4f55\u8bdd\u9898</li> <li>\u26a1 \u4e1a\u4f59\u65f6\u95f4\u559c\u6b22\u6298\u817e\u535a\u5ba2\u3001\u73a9\u6ed1\u677f\u3001\u7814\u7a76\u5982\u4f55\u628a\u751f\u6d3b\u8fc7\u5f97\u50cf\u4ee3\u7801\u4e00\u6837\u53ef\u8fed\u4ee3</li> </ul>"},{"location":"authors/linxinji.html#_3","title":"\ud83d\udee0\ufe0f \u6280\u672f\u6808 &amp; \u5de5\u5177","text":"<p>\u524d\u7aef - JavaScript / TypeScript / Vue / React - HTML5 / CSS3 / Tailwind - Webpack / Vite</p> <p>\u5176\u4ed6 - Python\uff08\u57fa\u7840\uff09 / Node.js - Git / GitHub Actions - Markdown \u91cd\u5ea6\u7231\u597d\u8005</p>"},{"location":"authors/linxinji.html#_4","title":"\ud83d\udcdd \u4e00\u4e9b\u5199\u4f5c\u65b9\u5411","text":"<ul> <li>\u6280\u672f\u5b9e\u8df5\u4e2d\u7684\u601d\u8003\u4e0e\u8e29\u5751\u8bb0\u5f55</li> <li>\u4e2a\u4eba\u590d\u76d8\u7684\u65b9\u6cd5\u8bba\uff08\u628a\u751f\u6d3b\u5f53\u4f5c\u7cfb\u7edf\u6765\u8fed\u4ee3\uff09</li> <li>\u4ee3\u7801\u4e0e\u54f2\u5b66\u7684\u6709\u8da3\u7c7b\u6bd4\uff08\u5982 Bug \u4e0e\u4e1a\u529b\u3001\u91cd\u6784\u4e0e\u4fee\u884c\uff09</li> </ul>"},{"location":"authors/linxinji.html#_5","title":"\ud83d\udceb \u627e\u5230\u6211","text":"<ul> <li>GitHub\uff1a@LinXinJi</li> <li>\u535a\u5ba2\uff1aair-is-full.com\uff08\u5efa\u8bbe\u4e2d\uff09</li> <li>\u90ae\u7bb1\uff1a2721124272@qq.com</li> </ul> <p>\u201c\u751f\u6d3b\u5982\u4ee3\u7801\uff0c\u4ece\u4e0d\u4e00\u6b21\u6210\u578b\u3002\u552f\u6709\u4e0d\u65ad\u91cd\u6784\uff0c\u624d\u80fd\u8fd0\u884c\u5f97\u66f4\u987a\u7545\u3002\u201d</p>"},{"location":"blog/index.html","title":"Git my Life","text":"<p>\u300c<code>Git my Life</code>\u300d\u8fd9\u91cc\u662f\u6211\u7684\u4e2a\u4eba\u590d\u76d8\u7a7a\u95f4\uff0c\u8bb0\u5f55\u7740\u4e00\u6b21\u6b21\u91cd\u6784\u4e0e\u8fed\u4ee3\u7684\u75d5\u8ff9\u3002</p> <p>\u751f\u6d3b\u5982\u540c\u4ee3\u7801\uff0c\u4ece\u4e0d\u4e00\u6b21\u6210\u578b\uff1a\u603b\u6709 Bug \u9700\u8981\u5b9a\u4f4d\uff0c\u603b\u6709\u903b\u8f91\u9700\u8981\u4f18\u5316\uff0c\u603b\u6709\u67b6\u6784\u9700\u8981\u63a8\u7ffb\u91cd\u6765\u3002\u6211\u5b66\u7740\u50cf\u5bf9\u5f85\u9879\u76ee\u4e00\u6837\u5bf9\u5f85\u81ea\u5df1\u2014\u2014\u5b9a\u671f\u56de\u987e\u3001\u52c7\u6562\u6467\u6bc1\u3001\u8010\u5fc3\u91cd\u5efa\u3002</p> <p>\u5982\u679c\u4f60\u4e5f\u5728\u6e4d\u6025\u7684\u6cb3\u6d41\u4e2d\u5bfb\u627e\u65b9\u5411\uff0c\u6216\u8bb8\u8fd9\u4e9b\u5173\u4e8e\u52a8\u9759\u3001\u6467\u6bc1\u4e0e\u91cd\u6784\u7684\u601d\u8003\uff0c\u80fd\u4e3a\u4f60\u5e26\u6765\u4e00\u4e1d\u542f\u53d1\uff01\u6b22\u8fce\u540c\u884c\uff01</p>"},{"location":"blog/2026/02/16/%E6%96%B0%E5%B9%B4%E6%96%B0%E6%B0%94%E8%B1%A1.html","title":"\u9664\u5915\u591c\uff1a\u91cd\u542f\u4eba\u751f\u7684\u7248\u672c\u53f7","text":"<p>\u5e06\u5f71\u5e7f\u573a\u7684\u7206\u7af9\u58f0\u4e0d\u7edd\u4e8e\u8033\uff0c\u65e7\u5e74\u7684\u6700\u540e\u4e00\u5929\uff0c\u5c31\u8fd9\u6837\u5728\u70df\u706b\u6c14\u548c\u56e2\u5706\u996d\u7684\u4f59\u6e29\u4e2d\uff0c\u7f13\u7f13\u8d70\u5411\u5c3e\u58f0\u3002</p> <p>\u6bcf\u5e74\u6b64\u523b\uff0c\u4eba\u4eec\u603b\u7231\u8bf4\u201c\u8f9e\u65e7\u8fce\u65b0\u201d\u3002\u53ef\u5982\u4eca\u6211\u624d\u6df1\u77e5\uff0c\u8f9e\u65e7\u5bb9\u6613\uff0c\u8fce\u65b0\u96be\u3002</p> <p>\u800c\u6211\u9009\u62e9\u5728\u4eca\u5929\uff0c\u5199\u4e0b\u8fd9\u7bc7\u6587\u7ae0\uff0c\u4f5c\u4e3a\u5f00\u542f\u6211\u4eba\u751f\u65b0\u65c5\u7a0b\u7684\u8d77\u70b9\u3002</p>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/16/%E6%96%B0%E5%B9%B4%E6%96%B0%E6%B0%94%E8%B1%A1.html#_2","title":"\u56de\u671b\uff1a\u90a3\u4e9b\u88ab\u88f9\u631f\u7684\u65e5\u5b50","text":"<p>\u8fc7\u53bb\u5f88\u957f\u4e00\u6bb5\u65f6\u95f4\uff0c\u6211\u5e38\u89c9\u5f97\u81ea\u5df1\u88ab\u4e00\u80a1\u65e0\u540d\u7684\u529b\u91cf\u88f9\u631f\u7740\u524d\u884c\u3002\u50cf\u7f6e\u8eab\u6e4d\u6025\u7684\u6cb3\u6d41\uff0c\u62fc\u547d\u6323\u624e\u5374\u4e8b\u500d\u529f\u534a\uff0c\u5f85\u5230\u7b4b\u75b2\u529b\u5c3d\uff0c\u4fbf\u7d22\u6027\u8eba\u5e73\uff0c\u4efb\u7531\u81ea\u5df1\u9893\u5e9f\u3001\u6446\u70c2\u3002</p> <p>\u90a3\u65f6\u4e0d\u61c2\uff0c\u751f\u6d3b\u4e0d\u662f\u4e00\u573a\u9700\u8981\u786c\u625b\u7684\u6218\u5f79\uff0c\u800c\u662f\u4e00\u95e8\u9700\u8981\u8c03\u9002\u7684\u7cfb\u7edf\u3002</p> <p>\u5982\u4eca\u6211\u5f00\u59cb\u7740\u624b\u6784\u5efa\u81ea\u5df1\u7684\u201c\u751f\u6d3b\u7248\u672c\u7ba1\u7406\u7cfb\u7edf\u201d\uff0c\u628a\u8fc7\u53bb\u7684\u7ecf\u9a8c\u3001\u4f53\u9a8c\u3001\u611f\u609f\u3001\u601d\u8003\u3001\u8ba1\u5212\u3001\u76ee\u6807\uff0c\u90fd\u6574\u7406\u6210\u4e00\u7cfb\u5217\u7684\u7248\u672c\uff0c\u9010\u6b65\u8fed\u4ee3\uff0c\u5f62\u6210\u81ea\u5df1\u7684\u201c\u4eba\u751f\u7248\u672c\u201d\u3002\u901a\u8fc7\u5728\u7f51\u7ad9\u91cc\u5199\u6587\u7ae0\uff0c\u8bb0\u5f55\u81ea\u5df1\u7684\u5fc3\u8def\u5386\u7a0b\uff0c\u4e5f\u8bb0\u5f55\u81ea\u5df1\u7684\u6210\u957f\u4e0e\u6536\u83b7\u3002</p> <p>\u6bcf\u4e00\u6b21\u590d\u76d8\uff0c\u90fd\u662f\u4e00\u6b21\u7248\u672c\u8fed\u4ee3\uff1a\u56de\u987e\u8fc7\u53bb\u7684\u884c\u4e3a\uff0c\u91cd\u6784\u5f53\u4e0b\u7684\u8ba4\u77e5\uff0c\u63a8\u6f14\u51fa\u66f4\u597d\u7684\u672a\u6765\u7248\u672c\u3002</p> <p>\u5199\u6587\u7ae0\u5982\u6b64\uff0c\u521b\u5efa\u7f51\u7ad9\u5982\u6b64\uff0c\u751f\u6d3b\u4ea6\u7136\u3002\u63a8\u5012\u91cd\u6765\u4e0d\u53ef\u6015\uff0c\u53ef\u6015\u7684\u662f\u4ece\u672a\u60f3\u8fc7\u91cd\u5efa\u3002</p>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/16/%E6%96%B0%E5%B9%B4%E6%96%B0%E6%B0%94%E8%B1%A1.html#_3","title":"\u6b64\u523b\uff1a\u7ad9\u5728\u65b0\u65e7\u4e4b\u4ea4\u7684\u8def\u53e3","text":"<p>\u9664\u5915\u591c\uff0c\u662f\u65f6\u95f4\u7559\u7ed9\u6211\u4eec\u7684\u5929\u7136\u201c\u65ad\u70b9\u201d\u3002</p> <p>\u5982\u679c\u628a\u4eba\u751f\u6bd4\u4f5c\u4ee3\u7801\uff0c\u4eca\u5929\u5c31\u662f\u4e00\u6b21\u91cd\u8981\u7684\u7248\u672c\u53d1\u5e03\u65e5\u3002\u65e7\u7684\u4e00\u5e74\u5373\u5c06\u5f52\u6863\uff0c\u65b0\u7684\u4e00\u5e74\u7b49\u5f85\u5199\u5165\u3002\u7ad9\u5728\u8fd9\u4e2a\u627f\u4e0a\u542f\u4e0b\u7684\u8282\u70b9\uff0c\u6700\u9002\u5408\u505a\u4e00\u4ef6\u4e8b\uff1a</p> <p>\u505c\u4e0b\u6765\uff0c\u5ba1\u89c6\u6b63\u5728\u8fd0\u884c\u7684\u8fd9\u4e2a\u201c\u81ea\u5df1\u201d\u3002</p> <p>\u54ea\u4e9b\u529f\u80fd\u8fd0\u884c\u987a\u7545\uff0c\u503c\u5f97\u4fdd\u7559\uff1f\u54ea\u4e9b\u903b\u8f91\u5b58\u5728\u7f3a\u9677\uff0c\u9700\u8981\u4f18\u5316\uff1f\u90a3\u4e9b\u53cd\u590d\u51fa\u73b0\u7684\u62a5\u9519\uff0c\u7a76\u7adf\u662f\u73af\u5883\u95ee\u9898\uff0c\u8fd8\u662f\u5e95\u5c42\u67b6\u6784\u7684\u6f0f\u6d1e\uff1f</p> <p>\u6211\u4e0d\u6307\u671b\u4e00\u591c\u4e4b\u95f4\u8131\u80ce\u6362\u9aa8\uff0c\u4f46\u81f3\u5c11\uff0c\u53ef\u4ee5\u4e3a\u81ea\u5df1\u8bbe\u5b9a\u4e00\u4e2a\u6e05\u6670\u7684\u8fed\u4ee3\u65b9\u5411\u3002</p>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/16/%E6%96%B0%E5%B9%B4%E6%96%B0%E6%B0%94%E8%B1%A1.html#_4","title":"\u542f\u7a0b\uff1a\u65b0\u7248\u672c\u7684\u89c4\u5212","text":"<p>\u65b0\u7684\u4e00\u5e74\uff0c\u6211\u60f3\u4e3a\u81ea\u5df1\u5199\u4e0b\u51e0\u884c\u65b0\u7684\u201c\u6838\u5fc3\u4ee3\u7801\u201d\uff1a</p> <p>1. \u5b66\u4f1a\u52a8\u9759\u7ed3\u5408\u7684\u667a\u6167</p> <p>\u50cf\u5199\u6587\u7ae0\u4e00\u6837\uff0c\u5199\u7684\u65f6\u5019\u5168\u8eab\u5fc3\u6295\u5165\uff0c\u5199\u5b8c\u540e\u51b7\u9759\u5ba1\u89c6\u3001\u91cd\u6784\u3002\u751f\u6d3b\u4e5f\u9700\u8981\u8fd9\u6837\u7684\u8282\u594f\u2014\u2014\u5728\u884c\u52a8\u4e2d\u4f53\u9a8c\uff0c\u5728\u9759\u9ed8\u4e2d\u53cd\u601d\u3002\u4e0d\u88ab\u6e4d\u6d41\u88f9\u631f\uff0c\u800c\u662f\u627e\u5230\u81ea\u5df1\u7684\u8282\u594f\uff0c\u987a\u6c34\u63a8\u821f\u3002</p> <p>2. \u62e5\u6709\u6467\u6bc1\u91cd\u6784\u7684\u52c7\u6c14</p> <p>\u6709\u4e9b\u65e7\u6a21\u5f0f\uff0c\u5fc5\u987b\u5f7b\u5e95\u63a8\u5012\u624d\u80fd\u91cd\u5efa\u3002\u5c31\u50cf\u8fd9\u4e2a\u7f51\u7ad9\uff0c\u6211\u91cd\u505a\u4e86\u597d\u51e0\u904d\uff0c\u6bcf\u4e00\u6b21\u4ece\u5934\u518d\u6765\uff0c\u90fd\u8ba9\u6211\u66f4\u6e05\u695a\u81ea\u5df1\u60f3\u8981\u4ec0\u4e48\u3002\u65b0\u7684\u4e00\u5e74\uff0c\u4e0d\u754f\u60e7\u63a8\u7ffb\u90a3\u4e9b\u4e0d\u518d\u9002\u7528\u7684\u4e60\u60ef\u3001\u8ba4\u77e5\uff0c\u751a\u81f3\u5173\u7cfb\u3002</p> <p>3. \u5b9a\u671f\u590d\u76d8\uff0c\u5c0f\u6b65\u8fed\u4ee3</p> <p>\u4e0d\u5fc5\u7b49\u5230\u5e74\u7ec8\u624d\u603b\u7ed3\u3002\u50cf\u654f\u6377\u5f00\u53d1\u4e00\u6837\uff0c\u8bbe\u7f6e\u6bcf\u65e5\u5fae\u590d\u76d8\u3001\u6bcf\u5468\u5c0f\u7ed3\u3001\u6bcf\u6708\u6df1\u5ea6\u590d\u76d8\u3002\u8ba9\u4f18\u5316\u6210\u4e3a\u4e60\u60ef\uff0c\u800c\u4e0d\u662f\u8d1f\u62c5\u3002</p> <p>4. \u62e5\u62b1\u4e0d\u786e\u5b9a\u6027</p> <p>\u4ee3\u7801\u4e16\u754c\u8bb2\u7a76\u786e\u5b9a\u6027\uff0c\u4f46\u751f\u6d3b\u4e0d\u662f\u3002\u90a3\u4e9b\u610f\u6599\u4e4b\u5916\u7684\u8f93\u5165\uff0c\u6216\u8bb8\u6b63\u662f\u7cfb\u7edf\u5347\u7ea7\u7684\u5951\u673a\u3002\u65b0\u7684\u4e00\u5e74\uff0c\u8bd5\u7740\u5bf9\u672a\u77e5\u4fdd\u6301\u5f00\u653e\uff0c\u628a\u201c\u610f\u5916\u201d\u5f53\u4f5c\u65b0\u529f\u80fd\u7684\u7075\u611f\u3002</p>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/16/%E6%96%B0%E5%B9%B4%E6%96%B0%E6%B0%94%E8%B1%A1.html#_5","title":"\u5199\u5728\u6700\u540e","text":"<p>\u7a97\u5916\u7206\u7af9\u6e10\u5bc6\uff0c\u96f6\u70b9\u7684\u949f\u58f0\u5373\u5c06\u6572\u54cd\u3002</p> <p>\u6211\u4e0d\u77e5\u9053\u65b0\u7684\u4e00\u5e74\u4f1a\u5e26\u6765\u600e\u6837\u7684\u8f93\u5165\uff0c\u4f46\u81f3\u5c11\uff0c\u6211\u4e3a\u81ea\u5df1\u5199\u4e0b\u4e86\u8fd9\u4efd\u58f0\u660e\u5f0f\u914d\u7f6e\u3002\u5269\u4e0b\u7684\uff0c\u4ea4\u7ed9\u8fd0\u884c\u65f6\uff0c\u4e5f\u4ea4\u7ed9\u90a3\u4e2a\u613f\u610f\u4e0d\u65ad\u91cd\u6784\u7684\u81ea\u5df1\u3002</p> <p>\u5982\u679c\u4f60\u4e5f\u7ad9\u5728\u65b0\u65e7\u4e4b\u4ea4\u7684\u8def\u53e3\uff0c\u4e0d\u59a8\u4e5f\u4e3a\u81ea\u5df1\u5199\u4e0b\u70b9\u4ec0\u4e48\u3002\u4e0d\u5fc5\u5b8c\u7f8e\uff0c\u4e0d\u5fc5\u5b8f\u5927\uff0c\u53ea\u8981\u771f\u5b9e\uff01</p> <p>\u613f\u6211\u4eec\u90fd\u80fd\u5728\u6e4d\u6025\u7684\u6cb3\u6d41\u4e2d\uff0c\u6e38\u5f97\u6e05\u723d\uff0c\u6d3b\u5f97\u81ea\u5728\uff01</p> <p>\u65b0\u5e74\u5feb\u4e50\uff01\u65b0\u65c5\u7a0b\uff0c\u5f00\u59cb\u4e86\uff01</p> <p>\u9769\u547d\u8fd8\u672a\u6210\u529f\uff0c\u540c\u5fd7\u4ecd\u9700\u52aa\u529b\uff01</p> <p>\u2014\u2014 \u5199\u4e8e 2026-02-16 \u9664\u5915\u591c\uff0c\u7248\u672c\u53f7 v1.0.0</p>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/17/happy-new-year.html","title":"\u3297\ufe0f Happy New Year","text":"<p>\u4e8e\u6625\u8282\u4e4b\u9645\uff0cxj \u5728\u8fd9\u795d\u798f\u5927\u5bb6\u65b0\u7684\u4e00\u5e74\u8eab\u4f53\u5065\u5eb7\uff0c\u79ef\u6781\u5411\u4e0a\uff0c\u52c7\u6562\u505a\u81ea\u5df1\uff01</p> <p>\u4e0b\u9762\uff0c\u662f\u6211\u5bf9\u81ea\u5df1\u65b0\u7684\u4e00\u5e74\uff0c\u8be5\u5982\u4f55\u8fc8\u51fa\u7b2c\u4e00\u6b65\u7684\u89c4\u5212...</p>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/17/happy-new-year.html#1","title":"1. \u4e60\u60ef\u517b\u6210","text":"<p>\u517b\u6210\u4e60\u60ef\u7684\u5173\u952e\uff0c\u5728\u4e8e\u4ed6\u8981\u60f3\u5f00\u673a\u81ea\u52a8\u542f\u52a8\u7684\u7a0b\u5e8f\u4e00\u6837\u5e38\u9a7b\u540e\u53f0\uff0c\u65f6\u4e0d\u65f6\u7684\u5192\u51fa\u6765\u63d0\u9192\u4f60\u3002</p> <p>\u4f8b\u5982\uff1a\u5f53\u957f\u65f6\u95f4\u8fd1\u8ddd\u79bb\u7528\u773c\u65f6\uff0c\u4f1a\u81ea\u52a8\u63d0\u9192\u81ea\u5df1\u773a\u671b\u8fdc\u65b9\uff0c\u8d77\u8eab\u6d3b\u52a8\uff0c\u7c7b\u4f3c\u4e8e\u6b64\u3002</p>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/17/happy-new-year.html#11","title":"1.1 \u751f\u6d3b\u4e60\u60ef","text":"<ul> <li> \u65e9\u7761\u65e9\u8d77\uff1a </li> </ul>","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/17/happy-new-year.html#12","title":"1.2 \u5b66\u4e60\u4e60\u60ef","text":"","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/17/happy-new-year.html#2","title":"2. \u76ee\u6807\u8bbe\u5b9a","text":"","tags":["\u65b0\u5e74"]},{"location":"blog/2026/02/16/standard-writing-principles.html","title":"\u5199\u4f5c\u539f\u5219\uff08\u4e00\uff09","text":"<p>\u5199\u4f5c\u548c\u7f16\u7801\u4e00\u6837\uff0c\u65e2\u662f\u4e00\u9879\u6280\u672f\uff0c\u4e5f\u662f\u4e00\u95e8\u827a\u672f\u3002\u5408\u7406\u7684\u8303\u5f0f\uff0c\u53ef\u4ee5\u5e2e\u52a9\u6211\u4eec\u63d0\u9ad8\u5199\u4f5c\u8d28\u91cf\uff0c\u8ba9\u6587\u7ae0\u66f4\u6709\u4ef7\u503c\u3002\u4e0b\u9762\u662f\u4e00\u4e9b\u5173\u4e8e\u5199\u590d\u76d8\u6587\u7ae0\u65f6\u7684\u539f\u5219\uff0c\u4f9b\u53c2\u8003\u3002</p>"},{"location":"blog/2026/02/16/standard-writing-principles.html#_2","title":"\u5199\u590d\u76d8\u535a\u5ba2\u7684\u5efa\u8bae","text":""},{"location":"blog/2026/02/16/standard-writing-principles.html#1","title":"1. \u50cf\u5199\u63d0\u4ea4\u65e5\u5fd7\u4e00\u6837\uff0c\u8bda\u5b9e\u800c\u5177\u4f53","text":"<p>\u590d\u76d8\u7684\u7075\u9b42\u5728\u4e8e\u771f\u5b9e\u3002\u4e0d\u5fc5\u7f8e\u5316\u81ea\u5df1\uff0c\u4e5f\u4e0d\u5fc5\u56de\u907f\u5931\u8d25\u3002\u5c31\u50cf\u4ee3\u7801\u63d0\u4ea4\u65f6\u5199 clear \u7684 commit message \u4e00\u6837\uff0c\u8bb0\u4e0b\u5f53\u65f6\u7684\u72b6\u6001\u3001\u51b3\u7b56\u3001\u60c5\u7eea\uff0c\u4ee5\u53ca\u6700\u7ec8\u7ed3\u679c\u3002\u6a21\u7cca\u7684\u201c\u4eca\u5929\u72b6\u6001\u4e0d\u597d\u201d\u4e0d\u5982\u201c\u56e0\u4e3a deadline \u903c\u8fd1\uff0c\u71ac\u591c\u8d76\u5de5\u5bfc\u81f4\u7b2c\u4e8c\u5929\u6548\u7387\u4f4e\u4e0b\u201d\u66f4\u6709\u590d\u76d8\u4ef7\u503c\u3002</p>"},{"location":"blog/2026/02/16/standard-writing-principles.html#2","title":"2. \u533a\u5206\u201c\u73b0\u8c61\u201d\u4e0e\u201c\u6839\u6e90\u201d","text":"<p>\u521d\u5199\u590d\u76d8\u5bb9\u6613\u505c\u7559\u5728\u8868\u9762\uff1a\u201c\u6211\u53c8\u62d6\u5ef6\u4e86\u201d\u201c\u6211\u7126\u8651\u4e86\u201d\u3002\u8bd5\u7740\u8ffd\u95ee\u4e00\u5c42\uff1a\u62d6\u5ef6\u80cc\u540e\u662f\u4efb\u52a1\u592a\u96be\uff0c\u8fd8\u662f\u5b8c\u7f8e\u4e3b\u4e49\u4f5c\u795f\uff1f\u7126\u8651\u80cc\u540e\u662f\u5bf9\u5931\u63a7\u7684\u6050\u60e7\uff0c\u8fd8\u662f\u7f3a\u4e4f\u660e\u786e\u76ee\u6807\uff1f\u50cf debug \u4e00\u6837\uff0c\u4ece\u62a5\u9519\u4fe1\u606f\u8ffd\u6eaf\u5230\u5e95\u5c42\u4ee3\u7801\uff0c\u627e\u5230\u771f\u6b63\u7684 root cause\u3002</p>"},{"location":"blog/2026/02/16/standard-writing-principles.html#3","title":"3. \u7528\u201c\u91cd\u6784\u601d\u7ef4\u201d\u4ee3\u66ff\u201c\u81ea\u8d23\u601d\u7ef4\u201d","text":"<p>\u590d\u76d8\u4e0d\u662f\u4e3a\u4e86\u5ba1\u5224\u81ea\u5df1\uff0c\u800c\u662f\u4e3a\u4e86\u4f18\u5316\u7cfb\u7edf\u3002\u9047\u5230\u95ee\u9898\uff0c\u53ef\u4ee5\u95ee\u81ea\u5df1\uff1a\u201c\u5982\u679c\u91cd\u6765\u4e00\u6b21\uff0c\u6211\u7684\u2018\u751f\u6d3b\u4ee3\u7801\u2019\u53ef\u4ee5\u600e\u6837\u91cd\u6784\uff1f\u201d\u662f\u628a\u5927\u51fd\u6570\u62c6\u6210\u5c0f\u6b65\u9aa4\uff08\u5206\u89e3\u4efb\u52a1\uff09\uff0c\u8fd8\u662f\u5f15\u5165\u5f02\u5e38\u5904\u7406\u673a\u5236\uff08\u63d0\u524d\u9884\u6848\uff09\uff1f\u628a\u6ce8\u610f\u529b\u4ece\u201c\u6211\u9519\u4e86\u201d\u8f6c\u5411\u201c\u7cfb\u7edf\u53ef\u4ee5\u5347\u7ea7\u201d\u3002</p>"},{"location":"blog/2026/02/16/standard-writing-principles.html#4","title":"4. \u4fdd\u6301\u8282\u594f\uff1a\u5c0f\u6b65\u8fed\u4ee3\uff0c\u5b9a\u671f\u56de\u987e","text":"<p>\u4e0d\u5fc5\u7b49\u5230\u4e00\u5e74\u624d\u590d\u76d8\u3002\u50cf\u654f\u6377\u5f00\u53d1\u4e00\u6837\uff0c\u53ef\u4ee5\u8bbe\u7f6e\u77ed\u671f\u51b2\u523a\uff08\u6bcf\u5929\u51e0\u5206\u949f\u56de\u987e\uff09\u3001\u4e2d\u671f\u8fed\u4ee3\uff08\u6bcf\u5468\u5c0f\u7ed3\uff09\u3001\u957f\u671f\u7248\u672c\u53d1\u5e03\uff08\u6708\u5ea6\u6216\u5b63\u5ea6\u6df1\u5ea6\u590d\u76d8\uff09\u3002\u91cd\u8981\u7684\u662f\u5f62\u6210\u4e60\u60ef\uff0c\u8ba9\u590d\u76d8\u6210\u4e3a\u751f\u6d3b\u6d41\u7a0b\u7684\u4e00\u90e8\u5206\uff0c\u800c\u4e0d\u662f\u8d1f\u62c5\u3002</p>"},{"location":"blog/2026/02/16/standard-writing-principles.html#5","title":"5. \u8bb0\u5f55\u201c\u91cd\u6784\u540e\u201d\u7684\u8fd0\u884c\u6548\u679c","text":"<p>\u4e00\u6b21\u6709\u6548\u7684\u590d\u76d8\uff0c\u5e94\u8be5\u80fd\u5e26\u6765\u884c\u4e3a\u4e0a\u7684\u6539\u53d8\u3002\u4e0d\u59a8\u5728\u540e\u7eed\u535a\u5ba2\u4e2d\u8ddf\u8e2a\u8fd9\u4e9b\u53d8\u5316\uff0c\u5c31\u50cf\u8bb0\u5f55\u7cfb\u7edf\u4f18\u5316\u540e\u7684\u6027\u80fd\u63d0\u5347\uff1a\u201c\u91c7\u7528\u756a\u8304\u5de5\u4f5c\u6cd5\u540e\uff0c\u6bcf\u5929\u6709\u6548\u5de5\u4f5c\u65f6\u95f4\u4ece 2 \u5c0f\u65f6\u63d0\u5347\u5230\u4e86 4 \u5c0f\u65f6\u201d\u2014\u2014\u7528\u6570\u636e\u6216\u611f\u53d7\u9a8c\u8bc1\u590d\u76d8\u7684\u6548\u679c\uff0c\u4e5f\u8ba9\u8bfb\u8005\u770b\u5230\u771f\u5b9e\u7684\u6210\u957f\u8f68\u8ff9\u3002</p>"},{"location":"blog/2026/02/16/standard-writing-principles.html#6","title":"6. \u62e5\u62b1\u201c\u6467\u6bc1\u201d\u7684\u52c7\u6c14","text":"<p>\u6709\u4e9b\u65e7\u6a21\u5f0f\u5fc5\u987b\u5f7b\u5e95\u63a8\u5012\u624d\u80fd\u91cd\u5efa\u3002\u5982\u679c\u67d0\u6b21\u590d\u76d8\u8ba9\u4f60\u610f\u8bc6\u5230\u9700\u8981\u505a\u51fa\u91cd\u5927\u6539\u53d8\uff0c\u4e0d\u8981\u5bb3\u6015\uff0c\u5927\u80c6\u5199\u4e0b\u6765\u3002\u6467\u6bc1\u7684\u8fc7\u7a0b\u6216\u8bb8\u75db\u82e6\uff0c\u4f46\u6b63\u5982\u91cd\u6784\u4ee3\u7801\u65f6\u7684\u6682\u65f6\u6df7\u4e71\uff0c\u4e4b\u540e\u8fce\u6765\u7684\u662f\u66f4\u6e05\u6670\u7684\u67b6\u6784\u3002\u4f60\u7684\u5766\u8bda\u672c\u8eab\uff0c\u5c31\u662f\u4e00\u79cd\u529b\u91cf\u3002</p> <p>\u6700\u540e\uff0c\u8bb0\u5f97\u7559\u767d\u3002\u751f\u6d3b\u4e0d\u662f\u4ee3\u7801\uff0c\u4e0d\u9700\u8981\u6bcf\u4e00\u884c\u90fd\u5199\u6ee1\u903b\u8f91\u3002\u5076\u5c14\u7684\u968f\u673a\u6f2b\u6b65\uff0c\u6216\u8bb8\u6b63\u662f\u7075\u611f\u7684\u6765\u6e90\u3002\u795d\u4f60\u5728\u201c\u7248\u672c\u8fed\u4ee3\u201d\u4e2d\uff0c\u8d8a\u6d3b\u8d8a\u50cf\u81ea\u5df1\u3002</p>"},{"location":"blog/archive/2026.html","title":"2026","text":""},{"location":"blog/category/%E5%90%AF%E7%A8%8B.html","title":"\u542f\u7a0b","text":""},{"location":"blog/category/%E5%86%99%E4%BD%9C%E8%A7%84%E8%8C%83.html","title":"\u5199\u4f5c\u89c4\u8303","text":""},{"location":"blog/authors/linxinji.html","title":"\u6797\u6b23\u7a37","text":""}]}